    public Map<String,Object> dashboard(){
        Map<String,Object> out=new LinkedHashMap<>();
        out.put("deviceTotal",count("SELECT COUNT(*) FROM access_device WHERE enabled=1"));
        out.put("deviceOnline",count("SELECT COUNT(*) FROM access_device WHERE enabled=1 AND online_status='ONLINE'"));
        out.put("longTermActive",count("SELECT COUNT(*) FROM access_person WHERE person_type='LONG_TERM' AND person_status='ACTIVE'"));
        out.put("pendingApproval",count("SELECT COUNT(*) FROM visitor_appointment WHERE status='PENDING_APPROVAL'"));
        out.put("expiring30Days",count("SELECT COUNT(*) FROM access_person WHERE person_status='ACTIVE' AND valid_to BETWEEN NOW() AND DATE_ADD(NOW(),INTERVAL 30 DAY)"));
        out.put("pendingReview",count("SELECT COUNT(*) FROM access_person_review WHERE status='PENDING'"));
        out.put("todayEvents",count("SELECT COUNT(*) FROM access_event WHERE event_time>=CURRENT_DATE"));
        out.putAll(eventSyncService.analysisMetrics());
        out.put("recentEvents",jdbc.queryForList("SELECT e.id,e.event_time eventTime,e.direction,e.result,p.person_name personName,d.device_name deviceName,ap.point_name pointName FROM access_event e JOIN access_device d ON d.id=e.device_id JOIN access_point ap ON ap.id=d.access_point_id LEFT JOIN access_person p ON p.id=e.person_id ORDER BY e.event_time DESC LIMIT 20"));
        return out;
    }

    public List<Map<String,Object>> points(){return jdbc.queryForList("SELECT id,point_code pointCode,point_name pointName,location,floor_code floorCode,description,enabled,created_at createdAt,updated_at updatedAt FROM access_point ORDER BY enabled DESC,point_name");}
    @Transactional public Map<String,Object> savePoint(Long id,Map<String,Object>b){required(b,"pointCode","门禁点编码不能为空");required(b,"pointName","门禁点名称不能为空");if(id==null){jdbc.update("INSERT INTO access_point(point_code,point_name,location,floor_code,description,enabled) VALUES(?,?,?,?,?,?)",text(b,"pointCode"),text(b,"pointName"),text(b,"location"),text(b,"floorCode"),text(b,"description"),boolInt(b,"enabled",1));id=lastId();}else jdbc.update("UPDATE access_point SET point_code=?,point_name=?,location=?,floor_code=?,description=?,enabled=? WHERE id=?",text(b,"pointCode"),text(b,"pointName"),text(b,"location"),text(b,"floorCode"),text(b,"description"),boolInt(b,"enabled",1),id);return one("SELECT id,point_code pointCode,point_name pointName,location,floor_code floorCode,description,enabled FROM access_point WHERE id=?",id);}

    public List<Map<String,Object>> devices(){return jdbc.queryForList("SELECT d.id,d.access_point_id accessPointId,p.point_name pointName,d.device_code deviceCode,d.device_name deviceName,d.direction,d.model,d.serial_number serialNumber,d.ip_address ipAddress,d.login_username loginUsername,(d.password_ciphertext IS NOT NULL) credentialConfigured,d.http_port httpPort,d.sdk_port sdkPort,d.firmware_version firmwareVersion,d.isapi_enabled isapiEnabled,d.online_status onlineStatus,d.last_connected_at lastConnectedAt,d.last_sync_at lastSyncAt,d.read_only_mode readOnlyMode,d.enabled,d.remark FROM access_device d JOIN access_point p ON p.id=d.access_point_id ORDER BY p.point_name,d.direction");}
    public Map<String,Object> probeDevice(Map<String,Object>b){HikvisionIsapiClient.DeviceInfo d=isapi.probe(text(b,"ipAddress"),intValue(b.get("httpPort"),80),text(b,"loginUsername"),text(b,"password"));return deviceInfo(d);}
    @Transactional public Map<String,Object> discoverDevice(Long id){Map<String,Object>d=one("SELECT ip_address ipAddress,http_port httpPort,login_username loginUsername,password_ciphertext passwordCiphertext,password_iv passwordIv FROM access_device WHERE id=?",id);String cipher=Objects.toString(d.get("passwordCiphertext"),""),iv=Objects.toString(d.get("passwordIv"),"");if(cipher.isBlank())bad("该设备没有保存登录凭据，请先编辑设备");String password=crypto.decrypt(cipher,iv);Map<String,Object>result=isapi.discover(Objects.toString(d.get("ipAddress"),""),intValue(d.get("httpPort"),80),Objects.toString(d.get("loginUsername"),""),password);jdbc.update("UPDATE access_device SET online_status='ONLINE',last_connected_at=NOW() WHERE id=?",id);saveCapabilities(id,result);return result;}
    @Transactional public Map<String,Object> setDeviceWriteMode(Long id,boolean enabled){if(count("SELECT COUNT(*) FROM access_device WHERE id="+id)==0)throw BizException.notFound("设备不存在");jdbc.update("UPDATE access_device SET read_only_mode=? WHERE id=?",enabled?0:1,id);return one("SELECT id,device_name deviceName,direction,read_only_mode readOnlyMode FROM access_device WHERE id=?",id);}
    private void saveCapabilities(Long deviceId,Map<String,Object>result){Map<String,String>codes=Map.of("PERSON_READ","personReadSupported","PERSON_CAPABILITY","personCapabilityAvailable","FACE_CAPABILITY","faceCapabilityAvailable","FACE_RECORD_CAPABILITY","faceRecordCapabilityAvailable","ID_CARD_CAPABILITY","idCardCapabilityAvailable","EVENT_SUBSCRIPTION","eventSubscriptionSupported");for(var entry:codes.entrySet())jdbc.update("INSERT INTO access_device_capability(device_id,capability_code,supported,detail_json,probed_at) VALUES(?,?,?,?,NOW()) ON DUPLICATE KEY UPDATE supported=VALUES(supported),detail_json=VALUES(detail_json),probed_at=NOW()",deviceId,entry.getKey(),Boolean.TRUE.equals(result.get(entry.getValue()))?1:0,null);}
    @Transactional public Map<String,Object> startPersonScan(String username){Integer running=jdbc.queryForObject("SELECT COUNT(*) FROM access_person_scan_job WHERE status IN ('PENDING','RUNNING')",Integer.class);if(running!=null&&running>0)bad("已有人员扫描任务正在执行，请稍后查看");jdbc.update("INSERT INTO access_person_scan_job(status,created_by) VALUES('PENDING',?)",username);Long id=lastId();scanService.scan(id);return one("SELECT id,status,created_at createdAt FROM access_person_scan_job WHERE id=?",id);}
    public Map<String,Object> latestPersonScan(){List<Map<String,Object>>jobs=jdbc.queryForList("SELECT id,status,device_total deviceTotal,device_completed deviceCompleted,person_rows personRows,unique_persons uniquePersons,common_persons commonPersons,only_entry onlyEntry,only_exit onlyExit,conflict_persons conflictPersons,message,started_at startedAt,completed_at completedAt,created_at createdAt FROM access_person_scan_job ORDER BY id DESC LIMIT 1");if(jobs.isEmpty())return Map.of();Map<String,Object>job=new LinkedHashMap<>(jobs.get(0));Long id=longValue(job.get("id"));job.put("differences",jdbc.queryForList("SELECT s.employee_no employeeNo,MAX(CASE WHEN d.direction='ENTRY' THEN s.person_name END) entryName,MAX(CASE WHEN d.direction='EXIT' THEN s.person_name END) exitName,MAX(CASE WHEN d.direction='ENTRY' THEN s.valid_to END) entryValidTo,MAX(CASE WHEN d.direction='EXIT' THEN s.valid_to END) exitValidTo,GROUP_CONCAT(DISTINCT d.direction) directions FROM access_person_snapshot s JOIN access_device d ON d.id=s.device_id WHERE s.scan_job_id=? GROUP BY s.employee_no HAVING COUNT(DISTINCT d.direction)<2 OR COUNT(DISTINCT COALESCE(s.person_name,''))>1 OR COUNT(DISTINCT COALESCE(s.valid_to,'1000-01-01'))>1 ORDER BY s.employee_no LIMIT 100",id));return job;}
    @Transactional public Map<String,Object> importLatestPersonScan(){Map<String,Object>job=one("SELECT id FROM access_person_scan_job WHERE status='COMPLETED' ORDER BY id DESC LIMIT 1");Long jobId=longValue(job.get("id"));List<Map<String,Object>>rows=jdbc.queryForList("SELECT s.*,d.direction FROM access_person_snapshot s JOIN access_device d ON d.id=s.device_id WHERE s.scan_job_id=? ORDER BY s.employee_no,d.direction",jobId);Map<String,List<Map<String,Object>>>groups=new LinkedHashMap<>();for(Map<String,Object>row:rows)groups.computeIfAbsent(Objects.toString(row.get("employee_no"),""),k->new ArrayList<>()).add(row);int created=0,updated=0,conflicts=0,withFace=0,withId=0;for(var group:groups.entrySet()){String employee=group.getKey();if(employee.isBlank())continue;List<Map<String,Object>>items=group.getValue();Map<String,Object>preferred=items.stream().filter(x->"ENTRY".equals(x.get("direction"))).findFirst().orElse(items.get(0));String name=Objects.toString(preferred.get("person_name"),"").trim();if(name.isBlank())name="待补充姓名-"+employee;Set<String>names=new HashSet<>();Set<String>ends=new HashSet<>();Timestamp from=null,to=null;boolean face=false;for(Map<String,Object>x:items){String n=Objects.toString(x.get("person_name"),"").trim();if(!n.isBlank())names.add(n);Object vf=x.get("valid_from"),vt=x.get("valid_to");if(vf instanceof Timestamp t&&(from==null||t.before(from)))from=t;if(vt instanceof Timestamp t){ends.add(t.toString());if(to==null||t.after(to))to=t;}face=face||intValue(x.get("face_count"),0)>0;}boolean conflict=names.size()>1||ends.size()>1;if(conflict)conflicts++;if(face)withFace++;List<Map<String,Object>>existing=jdbc.queryForList("SELECT id FROM access_person WHERE employee_no=? ORDER BY id LIMIT 1",employee);Long personId;if(existing.isEmpty()){String personNo="DEV-"+(employee.length()>60?employee.substring(0,60):employee);String status=to!=null&&to.before(Timestamp.valueOf(LocalDateTime.now()))?"EXPIRED":"ACTIVE";jdbc.update("INSERT INTO access_person(person_no,person_name,person_type,employee_no,valid_from,valid_to,face_status,source_type,managed_by_system,person_status,review_status,approval_status,remark) VALUES(?,?,'LONG_TERM',?,?,?,?, 'DEVICE_LEGACY',0,?,?,?,?)",personNo,name,employee,from,to,face?"PRESENT":"MISSING",status,conflict?"PENDING":"NONE",conflict?"PENDING":"IMPORTED",conflict?"设备姓名或有效期存在差异，需人工复核":"设备存量人员只读导入");personId=lastId();created++;}else{personId=longValue(existing.get(0).get("id"));jdbc.update("UPDATE access_person SET person_name=?,valid_from=?,valid_to=?,face_status=?,review_status=?,updated_at=NOW() WHERE id=?",name,from,to,face?"PRESENT":"MISSING",conflict?"PENDING":"NONE",personId);updated++;}for(Map<String,Object>x:items)jdbc.update("INSERT INTO access_person_device(person_id,device_id,device_person_no,device_employee_no,device_person_name,device_phone,device_valid_from,device_valid_to,face_present,sync_status,raw_snapshot_json,last_read_at) VALUES(?,?,?,?,?,?,?,?,?,'DEVICE_LEGACY',?,NOW()) ON DUPLICATE KEY UPDATE device_person_no=VALUES(device_person_no),device_employee_no=VALUES(device_employee_no),device_person_name=VALUES(device_person_name),device_phone=VALUES(device_phone),device_valid_from=VALUES(device_valid_from),device_valid_to=VALUES(device_valid_to),face_present=VALUES(face_present),raw_snapshot_json=VALUES(raw_snapshot_json),last_read_at=NOW()",personId,x.get("device_id"),employee,employee,x.get("person_name"),x.get("phone"),x.get("valid_from"),x.get("valid_to"),intValue(x.get("face_count"),0)>0?1:0,x.get("raw_json"));List<Map<String,Object>>cards=jdbc.queryForList("SELECT card_no_ciphertext c,card_no_iv i,card_no_last4 l FROM access_card_snapshot WHERE scan_job_id=(SELECT MAX(id) FROM access_card_scan_job WHERE status='COMPLETED') AND employee_no=? AND id_number_format=1 LIMIT 1",employee);if(!cards.isEmpty()){Map<String,Object>card=cards.get(0);jdbc.update("UPDATE access_person SET id_number_ciphertext=COALESCE(id_number_ciphertext,?),id_number_iv=COALESCE(id_number_iv,?),id_number_last4=COALESCE(id_number_last4,?) WHERE id=?",card.get("c"),card.get("i"),card.get("l"),personId);withId++;}if(conflict)jdbc.update("INSERT INTO access_person_review(person_id,review_type,status,reason) SELECT ?,'DATA_CONFLICT','PENDING','入口与出口设备的姓名或有效期不一致' WHERE NOT EXISTS(SELECT 1 FROM access_person_review WHERE person_id=? AND review_type='DATA_CONFLICT' AND status='PENDING')",personId,personId);}Map<String,Object>out=new LinkedHashMap<>();out.put("scanJobId",jobId);out.put("created",created);out.put("updated",updated);out.put("total",created+updated);out.put("withFace",withFace);out.put("withIdNumber",withId);out.put("conflicts",conflicts);out.put("message","已导入本系统，未修改设备资料");return out;}
    @Transactional public void normalizeImportedPersons(){jdbc.update("UPDATE access_person SET person_no=CAST(id AS CHAR)");jdbc.update("UPDATE access_person p SET p.phone=(SELECT NULLIF(s.phone,'') FROM access_person_snapshot s WHERE s.employee_no=p.employee_no AND NULLIF(s.phone,'') IS NOT NULL ORDER BY s.scan_job_id DESC,s.id DESC LIMIT 1) WHERE (p.phone IS NULL OR p.phone='') AND EXISTS(SELECT 1 FROM access_person_snapshot s2 WHERE s2.employee_no=p.employee_no AND NULLIF(s2.phone,'') IS NOT NULL)");}
    @Transactional public Map<String,Object> startCardScan(String username){Integer running=jdbc.queryForObject("SELECT COUNT(*) FROM access_card_scan_job WHERE status IN ('PENDING','RUNNING')",Integer.class);if(running!=null&&running>0)bad("已有卡片扫描任务正在执行，请稍后查看");jdbc.update("INSERT INTO access_card_scan_job(status,created_by) VALUES('PENDING',?)",username);Long id=lastId();cardScanService.scan(id);return one("SELECT id,status,created_at createdAt FROM access_card_scan_job WHERE id=?",id);}
    public Map<String,Object> latestCardScan(){List<Map<String,Object>>jobs=jdbc.queryForList("SELECT id,status,device_total deviceTotal,device_completed deviceCompleted,card_rows cardRows,unique_cards uniqueCards,common_cards commonCards,only_entry onlyEntry,only_exit onlyExit,id_number_cards idNumberCards,conflict_cards conflictCards,message,started_at startedAt,completed_at completedAt,created_at createdAt FROM access_card_scan_job ORDER BY id DESC LIMIT 1");return jobs.isEmpty()?Map.of():new LinkedHashMap<>(jobs.get(0));}
    @Transactional public Map<String,Object> saveDevice(Long id,Map<String,Object>b){Long pointId=longValue(b.get("accessPointId"));if(pointId==null)bad("请选择门禁点");String direction=upper(b,"direction","ENTRY");if(!Set.of("ENTRY","EXIT").contains(direction))bad("设备方向必须为入口或出口");required(b,"ipAddress","IP 地址不能为空");required(b,"loginUsername","设备用户名不能为空");String password=text(b,"password"),cipher=null,iv=null;if(password.isBlank()&&id!=null){Map<String,Object>old=one("SELECT password_ciphertext passwordCiphertext,password_iv passwordIv FROM access_device WHERE id=?",id);cipher=Objects.toString(old.get("passwordCiphertext"),"");iv=Objects.toString(old.get("passwordIv"),"");if(!cipher.isBlank())password=crypto.decrypt(cipher,iv);}if(password.isBlank())bad("设备密码不能为空");HikvisionIsapiClient.DeviceInfo info=isapi.probe(text(b,"ipAddress"),intValue(b.get("httpPort"),80),text(b,"loginUsername"),password);if(cipher==null||!text(b,"password").isBlank()){var enc=crypto.encrypt(password);cipher=enc.ciphertext();iv=enc.iv();}String code="HIK-"+info.serialNumber();String name=info.deviceName().isBlank()?((direction.equals("ENTRY")?"入口":"出口")+"门禁设备"):info.deviceName();Object[]a={pointId,code,name,direction,info.model(),info.serialNumber(),text(b,"ipAddress"),text(b,"loginUsername"),cipher,iv,intValue(b.get("httpPort"),80),8000,info.firmwareVersion(),1,1,boolInt(b,"enabled",1),text(b,"remark")};try{if(id==null){jdbc.update("INSERT INTO access_device(access_point_id,device_code,device_name,direction,model,serial_number,ip_address,login_username,password_ciphertext,password_iv,http_port,sdk_port,firmware_version,isapi_enabled,read_only_mode,enabled,remark,online_status,last_connected_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,'ONLINE',NOW())",a);id=lastId();}else{Object[]u=Arrays.copyOf(a,a.length+1);u[a.length]=id;jdbc.update("UPDATE access_device SET access_point_id=?,device_code=?,device_name=?,direction=?,model=?,serial_number=?,ip_address=?,login_username=?,password_ciphertext=?,password_iv=?,http_port=?,sdk_port=?,firmware_version=?,isapi_enabled=?,read_only_mode=?,enabled=?,remark=?,online_status='ONLINE',last_connected_at=NOW() WHERE id=?",u);}}catch(Exception ex){throw BizException.badRequest("该设备已经添加，或设备资料与现有记录冲突");}return one("SELECT d.id,d.access_point_id accessPointId,p.point_name pointName,d.device_code deviceCode,d.device_name deviceName,d.direction,d.model,d.serial_number serialNumber,d.ip_address ipAddress,d.login_username loginUsername,1 credentialConfigured,d.http_port httpPort,d.sdk_port sdkPort,d.firmware_version firmwareVersion,d.online_status onlineStatus,d.read_only_mode readOnlyMode,d.enabled FROM access_device d JOIN access_point p ON p.id=d.access_point_id WHERE d.id=?",id);}
    private Map<String,Object>deviceInfo(HikvisionIsapiClient.DeviceInfo d){Map<String,Object>m=new LinkedHashMap<>();m.put("deviceName",d.deviceName());m.put("model",d.model());m.put("serialNumber",d.serialNumber());m.put("firmwareVersion",d.firmwareVersion());m.put("firmwareReleasedDate",d.firmwareReleasedDate());m.put("deviceId",d.deviceId());m.put("macAddress",d.macAddress());m.put("ipAddress",d.ipAddress());return m;}

    public List<Map<String,Object>> persons(String keyword,String status){StringBuilder s=new StringBuilder("SELECT p.id,p.person_no personNo,p.system_user_id systemUserId,p.person_name personName,p.gender,p.person_type personType,p.employee_no employeeNo,p.phone,p.id_number_last4 idNumberLast4,p.organization_name organizationName,p.affiliation_type affiliationType,p.stall_id stallId,p.department_name departmentName,p.merchant_code merchantCode,p.valid_from validFrom,p.valid_to validTo,p.face_status faceStatus,p.source_type sourceType,p.managed_by_system managedBySystem,p.person_status personStatus,p.approval_status approvalStatus,p.last_passed_at lastPassedAt,p.review_status reviewStatus,p.remark,(SELECT COUNT(*) FROM access_person_device x WHERE x.person_id=p.id) deviceCount FROM access_person p WHERE 1=1");List<Object>a=new ArrayList<>();if(keyword!=null&&!keyword.isBlank()){s.append(" AND (p.person_name LIKE ? OR p.person_no LIKE ? OR p.employee_no LIKE ? OR p.phone LIKE ? OR p.organization_name LIKE ?)");String k="%"+keyword.trim()+"%";Collections.addAll(a,k,k,k,k,k);}if(status!=null&&!status.isBlank()){s.append(" AND p.person_status=?");a.add(status);}s.append(" ORDER BY p.updated_at DESC LIMIT 1000");return jdbc.queryForList(s.toString(),a.toArray());}
    @Transactional public Map<String,Object> savePerson(Long id,Map<String,Object>b){required(b,"personName","人员姓名不能为空");required(b,"phone","联系电话不能为空");Timestamp from=time(b.get("validFrom")),to=time(b.get("validTo"));if(from==null)from=Timestamp.valueOf(LocalDateTime.now());if(to==null&&"LONG_TERM".equals(upper(b,"personType","LONG_TERM")))to=Timestamp.valueOf(from.toLocalDateTime().plusYears(1));if(to!=null&&!to.after(from))bad("授权结束时间必须晚于开始时间");String no=id==null?("PENDING-"+UUID.randomUUID()):Objects.toString(one("SELECT person_no personNo FROM access_person WHERE id=?",id).get("personNo"),"");String idNumber=text(b,"idNumber"),idCipher=null,idIv=null,last4=null;if(!idNumber.isBlank()){String normalized=idNumber.toUpperCase(Locale.ROOT);if(!normalized.matches("\\d{17}[0-9X]"))bad("身份证号格式不正确");var encrypted=crypto.encrypt(normalized);idCipher=encrypted.ciphertext();idIv=encrypted.iv();last4=normalized.substring(14);}
        String gender=upper(b,"gender",idNumber.isBlank()?"UNKNOWN":genderFromId(idNumber));Object[]a={no,longValue(b.get("systemUserId")),text(b,"personName"),gender,upper(b,"personType","LONG_TERM"),text(b,"employeeNo"),text(b,"phone"),text(b,"organizationName"),upper(b,"affiliationType","EXTERNAL"),longValue(b.get("stallId")),text(b,"departmentName"),text(b,"merchantCode"),from,to,upper(b,"faceStatus","UNKNOWN"),upper(b,"sourceType","SYSTEM"),boolInt(b,"managedBySystem",0),upper(b,"personStatus","PENDING_REVIEW"),text(b,"remark")};if(id==null){jdbc.update("INSERT INTO access_person(person_no,system_user_id,person_name,gender,person_type,employee_no,phone,organization_name,affiliation_type,stall_id,department_name,merchant_code,valid_from,valid_to,face_status,source_type,managed_by_system,person_status,remark,id_number_ciphertext,id_number_iv,id_number_last4) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",concat(a,idCipher,idIv,last4));id=lastId();jdbc.update("UPDATE access_person SET person_no=CAST(id AS CHAR) WHERE id=?",id);}else{Object[]u=concat(a,id);jdbc.update("UPDATE access_person SET person_no=?,system_user_id=?,person_name=?,gender=?,person_type=?,employee_no=?,phone=?,organization_name=?,affiliation_type=?,stall_id=?,department_name=?,merchant_code=?,valid_from=?,valid_to=?,face_status=?,source_type=?,managed_by_system=?,person_status=?,remark=? WHERE id=?",u);if(idCipher!=null)jdbc.update("UPDATE access_person SET id_number_ciphertext=?,id_number_iv=?,id_number_last4=? WHERE id=?",idCipher,idIv,last4,id);}return person(id,false);}
    public Map<String,Object> person(Long id,boolean sensitive){Map<String,Object>p=one("SELECT id,person_no personNo,system_user_id systemUserId,person_name personName,gender,person_type personType,employee_no employeeNo,phone,id_number_last4 idNumberLast4,organization_name organizationName,affiliation_type affiliationType,stall_id stallId,department_name departmentName,merchant_code merchantCode,valid_from validFrom,valid_to validTo,face_status faceStatus,source_type sourceType,managed_by_system managedBySystem,person_status personStatus,approval_status approvalStatus,last_passed_at lastPassedAt,review_status reviewStatus,remark FROM access_person WHERE id=?",id);if(sensitive){Map<String,Object>secret=one("SELECT id_number_ciphertext c,id_number_iv i FROM access_person WHERE id=?",id);String c=Objects.toString(secret.get("c"),"");if(!c.isBlank())p.put("idNumber",crypto.decrypt(c,Objects.toString(secret.get("i"),"")));}else if(p.get("idNumberLast4")!=null)p.put("idNumber","**************"+p.get("idNumberLast4"));p.put("deviceMappings",jdbc.queryForList("SELECT x.id,x.device_id deviceId,d.device_name deviceName,d.direction,x.device_person_no devicePersonNo,x.device_employee_no deviceEmployeeNo,x.device_person_name devicePersonName,x.device_phone devicePhone,x.device_valid_from deviceValidFrom,x.device_valid_to deviceValidTo,x.face_present facePresent,x.card_no cardNo,x.sync_status syncStatus,x.first_discovered_at firstDiscoveredAt,x.last_read_at lastReadAt,x.last_error lastError FROM access_person_device x JOIN access_device d ON d.id=x.device_id WHERE x.person_id=?",id));return p;}
    public Map<String,Object> personFace(Long id){List<Map<String,Object>>rows=jdbc.queryForList("SELECT d.device_name deviceName,d.ip_address ipAddress,d.http_port httpPort,d.login_username loginUsername,d.password_ciphertext passwordCiphertext,d.password_iv passwordIv,x.raw_snapshot_json rawJson FROM access_person_device x JOIN access_device d ON d.id=x.device_id WHERE x.person_id=? AND x.face_present=1 ORDER BY CASE d.direction WHEN 'ENTRY' THEN 0 ELSE 1 END",id);for(Map<String,Object>row:rows){try{String raw=Objects.toString(row.get("rawJson"),"");String faceUrl=json.readTree(raw).path("faceURL").asText("");if(faceUrl.isBlank())continue;String password=crypto.decrypt(Objects.toString(row.get("passwordCiphertext"),""),Objects.toString(row.get("passwordIv"),""));byte[]image=isapi.readFaceImage(Objects.toString(row.get("ipAddress"),""),intValue(row.get("httpPort"),80),Objects.toString(row.get("loginUsername"),""),password,faceUrl);return Map.of("deviceName",Objects.toString(row.get("deviceName"),""),"mimeType","image/jpeg","dataBase64",Base64.getEncoder().encodeToString(image));}catch(Exception ignored){}}throw BizException.notFound("暂时无法从门禁设备读取该人员的人脸照片");}
    private String genderFromId(String id){return Character.digit(id.charAt(16),10)%2==1?"MALE":"FEMALE";}
    private Object[]concat(Object[]values,Object...tail){Object[]out=Arrays.copyOf(values,values.length+tail.length);System.arraycopy(tail,0,out,values.length,tail.length);return out;}
    public Map<String,Object> self(String username){List<Map<String,Object>>l=jdbc.queryForList("SELECT p.id FROM access_person p JOIN sys_user u ON u.id=p.system_user_id WHERE u.username=? LIMIT 1",username);if(l.isEmpty())return Map.of("person",Map.of(),"events",List.of(),"appointments",mineVisitors(username),"renewals",List.of());Long id=longValue(l.get(0).get("id"));Map<String,Object>out=new LinkedHashMap<>();out.put("person",person(id,false));out.put("events",events(username,true));out.put("appointments",mineVisitors(username));out.put("renewals",mineRenewals(username));return out;}
    @Transactional public Map<String,Object> claimSelf(String username,Map<String,Object>b,String clientIp){String phone=text(b,"phone"),idNumber=text(b,"idNumber").toUpperCase(Locale.ROOT);if(!phone.matches("1\\d{10}"))bad("请输入正确的手机号");if(!idNumber.matches("\\d{17}[0-9X]"))bad("请输入正确的身份证号");Map<String,Object>user=one("SELECT id FROM sys_user WHERE username=?",username);if(count("SELECT COUNT(*) FROM access_person WHERE system_user_id="+longValue(user.get("id")))>0)bad("当前账号已经认领人员档案");List<Map<String,Object>>candidates=jdbc.queryForList("SELECT id,system_user_id systemUserId,id_number_ciphertext c,id_number_iv i FROM access_person WHERE phone=?",phone);Long matched=null;for(Map<String,Object>candidate:candidates){String cipher=Objects.toString(candidate.get("c"),"");if(cipher.isBlank())continue;try{if(idNumber.equalsIgnoreCase(crypto.decrypt(cipher,Objects.toString(candidate.get("i"),"")))){if(candidate.get("systemUserId")!=null){claimLog(null,username,phone,idNumber,"FAILED","该人员档案已被其他账号认领",clientIp);bad("该人员档案已被其他账号认领，请联系管理员");}if(matched!=null){claimLog(null,username,phone,idNumber,"FAILED","匹配到多个人员档案",clientIp);bad("匹配到多个人员档案，请联系管理员处理");}matched=longValue(candidate.get("id"));}}catch(BizException ex){throw ex;}catch(Exception ignored){}}
        if(matched==null){claimLog(null,username,phone,idNumber,"FAILED","手机号与身份证号未匹配",clientIp);bad("手机号或身份证号与存量人员资料不一致");}jdbc.update("UPDATE access_person SET system_user_id=?,claimed_at=NOW(),claimed_username=?,managed_by_system=1,updated_at=NOW() WHERE id=? AND system_user_id IS NULL",user.get("id"),username,matched);jdbc.update("UPDATE sys_user SET phone=? WHERE id=?",phone,user.get("id"));claimLog(matched,username,phone,idNumber,"SUCCESS",null,clientIp);return self(username);}
    private void claimLog(Long personId,String username,String phone,String idNumber,String result,String reason,String clientIp){jdbc.update("INSERT INTO access_person_claim_log(person_id,username,phone_last4,id_number_last4,claim_result,failure_reason,client_ip) VALUES(?,?,?,?,?,?,?)",personId,username,phone.substring(Math.max(0,phone.length()-4)),idNumber.substring(Math.max(0,idNumber.length()-4)),result,reason,clientIp);}
    @Transactional public Map<String,Object> updateSelf(String username,Map<String,Object>b){
        Map<String,Object>user=one("SELECT id,display_name displayName,phone FROM sys_user WHERE username=?",username);required(b,"personName","姓名不能为空");required(b,"phone","联系电话不能为空");String type=upper(b,"affiliationType","EXTERNAL");if(!Set.of("STALL","PROPERTY","COMMERCIAL","EXTERNAL").contains(type))bad("单位类型不正确");Long stallId=longValue(b.get("stallId"));String organization=text(b,"organizationName");if("STALL".equals(type)){if(stallId==null)bad("请选择所属铺位");Map<String,Object>stall=one("SELECT s.stall_code stallCode,COALESCE(NULLIF(m.merchant_name,''),NULLIF(s.stall_name,''),s.stall_code) organizationName FROM stall s LEFT JOIN merchant m ON m.id=s.current_merchant_id WHERE s.id=?",stallId);organization=Objects.toString(stall.get("organizationName"),"");}
        String idNumber=text(b,"idNumber"),cipher=null,iv=null,last4=null,gender=upper(b,"gender","UNKNOWN");if(!idNumber.isBlank()&&!idNumber.contains("*")){String normalized=idNumber.toUpperCase(Locale.ROOT);if(!normalized.matches("\\d{17}[0-9X]"))bad("身份证号格式不正确");var enc=crypto.encrypt(normalized);cipher=enc.ciphertext();iv=enc.iv();last4=normalized.substring(14);gender=genderFromId(normalized);}
        List<Map<String,Object>>found=jdbc.queryForList("SELECT id FROM access_person WHERE system_user_id=? LIMIT 1",user.get("id"));if(found.isEmpty())bad("请先使用手机号和身份证号认领存量人员档案");Long id=longValue(found.get(0).get("id"));jdbc.update("UPDATE access_person SET person_name=?,gender=?,phone=?,organization_name=?,affiliation_type=?,stall_id=?,department_name=?,updated_at=NOW() WHERE id=?",text(b,"personName"),gender,text(b,"phone"),organization,type,stallId,text(b,"departmentName"),id);if(cipher!=null)jdbc.update("UPDATE access_person SET id_number_ciphertext=?,id_number_iv=?,id_number_last4=? WHERE id=?",cipher,iv,last4,id);jdbc.update("UPDATE sys_user SET display_name=?,phone=? WHERE id=?",text(b,"personName"),text(b,"phone"),user.get("id"));return self(username);
    }

    public List<Map<String,Object>> visitors(){return visitorRows("",new Object[0]);}
    public List<Map<String,Object>> mineVisitors(String username){return visitorRows(" WHERE v.applicant_username=? OR v.host_username=? OR EXISTS(SELECT 1 FROM sys_user u WHERE u.username=? AND u.phone=v.visitor_phone)",new Object[]{username,username,username});}
    public List<Map<String,Object>> renewalApplications(){return jdbc.queryForList("SELECT a.id,a.application_no applicationNo,a.application_type applicationType,a.status,a.person_id personId,p.person_no personNo,p.person_name personName,p.phone,p.organization_name organizationName,p.valid_to currentValidTo,a.requested_valid_from requestedValidFrom,a.requested_valid_to requestedValidTo,a.applicant_username applicantUsername,a.approved_by approvedBy,a.approved_at approvedAt,a.approval_note approvalNote,a.created_at createdAt FROM access_application a JOIN access_person p ON p.id=a.person_id WHERE a.application_type='RENEWAL' ORDER BY a.created_at DESC LIMIT 1000");}
    public List<Map<String,Object>> mineRenewals(String username){return jdbc.queryForList("SELECT a.id,a.application_no applicationNo,a.application_type applicationType,a.status,p.person_name personName,p.valid_to currentValidTo,a.requested_valid_from requestedValidFrom,a.requested_valid_to requestedValidTo,a.approved_by approvedBy,a.approved_at approvedAt,a.approval_note approvalNote,a.created_at createdAt FROM access_application a JOIN access_person p ON p.id=a.person_id WHERE a.application_type='RENEWAL' AND a.applicant_username=? ORDER BY a.created_at DESC",username);}
    @Transactional public Map<String,Object> requestRenewal(String username){Map<String,Object>p=one("SELECT p.id,p.valid_to validTo FROM access_person p JOIN sys_user u ON u.id=p.system_user_id WHERE u.username=? LIMIT 1",username);Long personId=longValue(p.get("id"));Integer pending=jdbc.queryForObject("SELECT COUNT(*) FROM access_application WHERE person_id=? AND application_type='RENEWAL' AND status IN ('PENDING_APPROVAL','SYNC_FAILED')",Integer.class,personId);if(pending!=null&&pending>0)bad("已有待处理的续期申请，请勿重复提交");Timestamp current=time(p.get("validTo"));LocalDateTime from=current==null||current.toLocalDateTime().isBefore(LocalDateTime.now())?LocalDateTime.now():current.toLocalDateTime();LocalDateTime to=from.plusYears(1);String no="RN"+LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyyMMddHHmmssSSS"));jdbc.update("INSERT INTO access_application(application_no,application_type,person_id,requested_valid_from,requested_valid_to,status,applicant_username) VALUES(?,'RENEWAL',?,?,?,'PENDING_APPROVAL',?)",no,personId,Timestamp.valueOf(from),Timestamp.valueOf(to),username);return one("SELECT id,application_no applicationNo,status,requested_valid_from requestedValidFrom,requested_valid_to requestedValidTo FROM access_application WHERE application_no=?",no);}
    public Map<String,Object> decideRenewal(Long id,Map<String,Object>b,String username){String decision=upper(b,"decision","");if(!Set.of("APPROVED","REJECTED").contains(decision))bad("审批结果必须为通过或拒绝");return provisionService.decideRenewal(id,decision,username,text(b,"approvalNote"));}
    private List<Map<String,Object>> visitorRows(String where,Object[]args){return jdbc.queryForList("SELECT v.id,v.appointment_no appointmentNo,v.visitor_name visitorName,v.gender,v.visitor_phone visitorPhone,v.id_number_last4 idNumberLast4,v.visitor_company visitorCompany,v.affiliation_type affiliationType,v.stall_id stallId,v.face_status faceStatus,v.host_username hostUsername,v.host_name hostName,v.host_department hostDepartment,v.visit_reason visitReason,v.valid_from validFrom,v.valid_to validTo,v.access_point_ids_json accessPointIdsJson,v.vehicle_no vehicleNo,v.companion_count companionCount,v.status,v.applicant_username applicantUsername,v.approved_by approvedBy,v.approved_at approvedAt,v.approval_note approvalNote,v.created_at createdAt FROM visitor_appointment v"+where+" ORDER BY v.created_at DESC LIMIT 1000",args);}
    public Map<String,Object> visitor(Long id){
        Map<String,Object> row=one("SELECT v.id,v.appointment_no appointmentNo,v.visitor_name visitorName,v.gender,v.visitor_phone visitorPhone,v.id_number_last4 idNumberLast4,v.visitor_company visitorCompany,v.affiliation_type affiliationType,v.stall_id stallId,s.stall_code stallCode,s.floor_code floorCode,v.face_status faceStatus,v.host_name hostName,v.visit_reason visitReason,v.valid_from validFrom,v.valid_to validTo,v.status,v.applicant_username applicantUsername,v.approved_by approvedBy,v.approved_at approvedAt,v.approval_note approvalNote,v.created_at createdAt FROM visitor_appointment v LEFT JOIN stall s ON s.id=v.stall_id WHERE v.id=?",id);
        row.put("attachments",attachments.list(id));
        row.put("syncTasks",jdbc.queryForList("SELECT t.id,t.batch_no batchNo,t.operation_type operationType,t.status,t.attempt_count attemptCount,t.device_response deviceResponse,t.last_error lastError,t.started_at startedAt,t.completed_at completedAt,d.device_name deviceName,d.direction FROM access_device_sync_task t JOIN access_device d ON d.id=t.device_id WHERE t.person_id=(SELECT visitor_person_id FROM visitor_appointment WHERE id=?) ORDER BY t.id DESC",id));
        row.put("devices",jdbc.queryForList("SELECT id,device_name deviceName,direction,online_status onlineStatus,read_only_mode readOnlyMode,enabled,isapi_enabled isapiEnabled FROM access_device WHERE enabled=1 AND isapi_enabled=1 ORDER BY direction,id"));
        return row;
    }
    public void requireVisitorAccess(Long id,String username,boolean viewAll){if(viewAll)return;Integer n=jdbc.queryForObject("SELECT COUNT(*) FROM visitor_appointment WHERE id=? AND applicant_username=?",Integer.class,id,username);if(n==null||n==0)throw BizException.forbidden("无权查看该预约资料");}
    @Transactional public Map<String,Object> createVisitor(Map<String,Object>b,String username){required(b,"visitorName","姓名不能为空");required(b,"visitorPhone","电话不能为空");String phone=text(b,"visitorPhone");if(!phone.matches("1\\d{10}"))bad("请输入正确的手机号");String idNumber=text(b,"idNumber").toUpperCase(Locale.ROOT);if(!idNumber.matches("\\d{17}[0-9X]"))bad("请输入正确的身份证号");String affiliation=upper(b,"affiliationType","");if(!Set.of("STALL","PROPERTY","COMMERCIAL").contains(affiliation))bad("请选择到访单位类型");Long stallId=longValue(b.get("stallId"));String company=text(b,"visitorCompany");if("STALL".equals(affiliation)){if(stallId==null)bad("请选择到访店铺");Map<String,Object>stall=one("SELECT COALESCE(NULLIF(m.merchant_name,''),NULLIF(s.stall_name,''),s.stall_code) company FROM stall s LEFT JOIN merchant m ON m.id=s.current_merchant_id WHERE s.id=?",stallId);company=Objects.toString(stall.get("company"),"");}else company="PROPERTY".equals(affiliation)?"物业部":"商管部";Timestamp from=time(b.get("validFrom"));if(from==null)from=Timestamp.valueOf(LocalDateTime.now());Timestamp to=time(b.get("validTo"));if(to==null)to=Timestamp.valueOf(from.toLocalDateTime().plusYears(1));if(!to.after(from))bad("结束日期必须晚于开始日期");var encrypted=crypto.encrypt(idNumber);String gender=genderFromId(idNumber),no="VA"+LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyyMMddHHmmssSSS"));jdbc.update("INSERT INTO visitor_appointment(appointment_no,visitor_name,gender,visitor_phone,id_number_ciphertext,id_number_iv,id_number_last4,visitor_company,affiliation_type,stall_id,host_username,host_name,host_department,visit_reason,valid_from,valid_to,access_point_ids_json,vehicle_no,companion_count,status,applicant_username) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,'PENDING_APPROVAL',?)",no,text(b,"visitorName"),gender,phone,encrypted.ciphertext(),encrypted.iv(),idNumber.substring(14),company,affiliation,stallId,username,company,company,"门禁授权申请",from,to,text(b,"accessPointIdsJson"),text(b,"vehicleNo"),0,username);return one("SELECT id,appointment_no appointmentNo,status FROM visitor_appointment WHERE appointment_no=?",no);}
    public Map<String,Object> decideVisitor(Long id,Map<String,Object>b,String username){String decision=upper(b,"decision","");if(!Set.of("APPROVED","REJECTED").contains(decision))bad("审批结果必须为通过或拒绝");return "APPROVED".equals(decision)?provisionService.approveVisitor(id,username,text(b,"approvalNote")):provisionService.rejectVisitor(id,username,text(b,"approvalNote"));}
    public Map<String,Object> revokeVisitor(Long id,Map<String,Object>b,String username){required(b,"reason","请填写撤销原因");return provisionService.revokeVisitor(id,username,text(b,"reason"));}

    @Transactional public void permanentlyDeleteVisitor(Long id){Map<String,Object>v=one("SELECT visitor_person_id personId,status FROM visitor_appointment WHERE id=?",id);Long personId=longValue(v.get("personId"));if(personId!=null){List<Long>apps=jdbc.query("SELECT id FROM access_application WHERE appointment_id=? OR person_id=?",(rs,n)->rs.getLong(1),id,personId);if(!apps.isEmpty()){String marks=String.join(",",Collections.nCopies(apps.size(),"?"));jdbc.update("DELETE FROM access_device_sync_task WHERE application_id IN ("+marks+")",apps.toArray());jdbc.update("DELETE FROM access_person_retention_snapshot WHERE application_id IN ("+marks+")",apps.toArray());jdbc.update("DELETE FROM access_application WHERE id IN ("+marks+")",apps.toArray());}jdbc.update("DELETE FROM access_person_review WHERE person_id=?",personId);jdbc.update("DELETE FROM access_person_device WHERE person_id=?",personId);jdbc.update("UPDATE access_event SET person_id=NULL WHERE person_id=?",personId);jdbc.update("DELETE FROM access_person_document WHERE person_id=?",personId);jdbc.update("DELETE FROM access_person_retention_snapshot WHERE person_id=?",personId);jdbc.update("UPDATE visitor_appointment SET visitor_person_id=NULL WHERE id=?",id);jdbc.update("DELETE FROM access_person WHERE id=? AND person_type='VISITOR'",personId);}attachments.deleteAll(id);jdbc.update("DELETE FROM visitor_appointment WHERE id=?",id);}

